import os,json,subprocess,stat,re
from pathlib import Path
P=Path
proj=P('/srv/projects')
def run(a,t=10):
 try:
  v=subprocess.run(a,text=True,capture_output=True,timeout=t)
  return {'rc':v.returncode,'out':v.stdout.strip()[:700]}
 except Exception as e:return {'rc':99,'error':type(e).__name__}
def typ(x):
 p=P(x)
 return 'symlink' if p.is_symlink() else 'dir' if p.is_dir() else 'file' if p.is_file() else 'absent'
root_names=sorted(p.name for p in proj.iterdir() if p.is_dir() and not p.is_symlink()) if proj.is_dir() else []
r={'physical_roots':root_names,'projects':{},'extra_locations':{},'services':{},'service_paths':{},'outside_refs':[],'crossproject_symlinks':[],'symlink_scan_dirs':0,'symlink_scan_complete':True,'system_programs':{},'old_rea':{},'git_clashes':[]}
services=['ssh','nginx','postgresql@16-main','pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-iptvpn-bot','pm2-telegram-robot-leads']
for name in services:
 state=run(['systemctl','is-active',name])
 a=run(['systemctl','show',name,'--property=FragmentPath,WorkingDirectory,User,Group,EnvironmentFiles,ExecStart','--no-pager'],10)
 lines=a.get('out','').splitlines()
 r['services'][name]=state.get('out')
 r['service_paths'][name]=[x[:300] for x in lines if x.startswith(('FragmentPath=','WorkingDirectory=','EnvironmentFiles=','User=','Group='))]
 base=P('/etc/systemd/system')/(name+'.service')
 if base.is_file():
  try:
   txt=base.read_text(errors='replace')
   r['service_paths'][name]+=[x[:350] for x in txt.splitlines() if x.strip().startswith(('ExecStart=','WorkingDirectory=','EnvironmentFile=','ReadWritePaths=','StateDirectory=','RuntimeDirectory='))][:22]
  except Exception:pass
for name in root_names:
 path=proj/name
 git=run(['git','-C',str(path),'rev-parse','--is-inside-work-tree'],5)
 remote=run(['git','-C',str(path),'remote','get-url','origin'],5) if git['rc']==0 else {}
 clean=run(['git','-C',str(path),'status','--porcelain','-uno'],5) if git['rc']==0 else {}
 status={'git_root':git['rc']==0,'origin':remote.get('out','')[:190],'tracked_changes':len(clean.get('out','').splitlines()),'top':[],'links':[]}
 for item in sorted(path.iterdir(),key=lambda q:q.name):
  if item.name in ('node_modules','.venv','__pycache__'):continue
  status['top'].append({'name':item.name,'kind':typ(item),'target':str(item.resolve(strict=False)) if item.is_symlink() else None})
  if len(status['top'])>=45:break
 r['projects'][name]=status
for pth in ['/srv/pink-iptv','/srv/fadego-staging','/srv/lowcost-europa','/etc/lowcost-europa','/etc/fadego-staging','/root/project-secrets','/root/project-secrets/lowcost-europa','/root/.pm2','/home/ubuntu/.pm2','/opt/hopper','/opt/rea','/home/ubuntu/.cache/rea','/home/ubuntu/.claude-flow','/home/ubuntu/.claude-server-commander','/home/ubuntu/.codex','/home/ubuntu/.gemini','/home/ubuntu/.npm','/home/ubuntu/.local/share/rea-github-transport','/var/www','/srv/projects/Engenheira-reversa','/srv/projects/REA-Trial']:
 p=P(pth)
 r['extra_locations'][pth]={'type':typ(p),'target':str(p.resolve(strict=False)) if p.is_symlink() else None,'top':[x.name for x in p.iterdir()][:35] if p.is_dir() and pth in ('/root/project-secrets','/etc/fadego-staging','/var/www') else []}
# Metadata-only external config references (never report env contents).
for d in ('/etc/systemd/system','/etc/nginx/sites-available','/etc/nginx/sites-enabled','/etc/cron.d','/usr/local/bin','/usr/local/sbin'):
 path=P(d)
 if not path.is_dir():continue
 for f in path.iterdir():
  try:
   if not f.is_file() or f.stat().st_size>300000:continue
   body=f.read_text(errors='replace')
   matches=sorted(set(re.findall(r'/(?:root/project-secrets|srv/projects|srv/pink-iptv|srv/fadego-staging|srv/lowcost-europa|opt/hopper|etc/fadego-staging|etc/lowcost-europa)[^\s"\x27;,)}]*',body)))
   if matches:r['outside_refs'].append({'file':str(f),'paths':matches[:18]})
  except Exception:pass
# Cross-project symlink scan excluding deep dependency trees; symlinks themselves included.
skip={'node_modules','.git','.pnpm-store','.venv','__pycache__','.npm','vendor','dist','build','site-packages'}
for name in root_names:
 top=proj/name
 for cur,ds,fs in os.walk(top,followlinks=False):
  r['symlink_scan_dirs']+=1
  if r['symlink_scan_dirs']>70000:
   r['symlink_scan_complete']=False
   ds[:]=[]
   break
  for n in ds+fs:
   p=P(cur)/n
   if not p.is_symlink():continue
   target=p.resolve(strict=False)
   if str(target).startswith(str(proj)+'/') and not str(target).startswith(str(top)+'/'):
    r['crossproject_symlinks'].append({'src':str(p),'target':str(target)})
  ds[:]=[x for x in ds if x not in skip]
 if not r['symlink_scan_complete']:break
for n in ('hopper','python3','node','npm','pm2','docker','blender','ffmpeg','java','git'):
 r['system_programs'][n]=run(['sh','-c','command -v '+n]).get('out','')
r['old_rea']={'final':typ('/srv/projects/Engenheira-reversa'),'trial':typ('/srv/projects/REA-Trial'),'hopper_apt':run(['dpkg-query','-W','hopper'])}
fs=os.statvfs('/')
r['disk']={'free_gib':round(fs.f_bavail*fs.f_frsize/1024**3,2),'total_gib':round(fs.f_blocks*fs.f_frsize/1024**3,2)}
print(json.dumps(r,separators=(',',':'),ensure_ascii=True))
